\section{Preliminaries}\label{sec:preliminary}

\vspace{.15cm}\noindent \textbf{Multigraph \ \ }
For a multigraph $G = (V, E)$, the edge set $E$ is a set of triples $(u, v, \alpha)$ such that $u$ and $v$ are two vertices in $V$, and $\alpha$ is a positive integer which represents the edge multiplicity of the edge with $u$ and $v$ as two endpoints. 
We assume $(u, v, \alpha)$ is equivalent to $(v, u, \alpha)$ so that for every two vertices $u$ and $v$, there is at most one triple with $u$ and $v$ as first two elements. 
For a graph $G$, we use $V(G)$ to denote the vertex set of $G$, and $E(G)$ to denote the edge set of $G$. 

each edge insertion or deletion for the simple graph corresponds to a constant number of multigraph updates with the following update operations:
\begin{itemize}
\item $\insertt(u, v, \alpha)$: insert edge $(u, v, \alpha)$ to the graph
\item $\delete(u, v)$: delete the edge with $u$ and $v$ as two endpoints from the graph, no matter what the edge multiplicity is 
\item $\insertt(v)$: insert a new vertex $v$  to the graph
\item $\delete(v)$: delete isolated vertex $v$ from the graph.
\end{itemize}

In this paper, unless specified, we assume graphs are undirected multigraphs with a constant number of neighbors.

\vspace{.15cm}\noindent \textbf{Notations \ \ }
We say $E'$ is an edge subset of $G = (V, E)$ if $E'$ is a subset of $E$.
For a subset of edges $E' \subset E$, 
we use $|E'|$ to denote $\sum_{(u, v, \alpha)\in E'}\alpha$, use $\endpoints(E')$ to denote the set of endpoints of all the edges in $E'$, and use $G\cut E'$ to denote the graph $(V, E\cut E')$. 

For a graph $G = (V, E)$ and a subset of vertices $V'\subset V$, 
we use $\vol_G(V')$ to denote the volume of $V'$ in $G$, which is defined as 
\[\vol_G(V') \defeq \sum_{u\in V'} \sum_{(u, v, \alpha) \in E} \alpha.\] 
We use $G[V']$ to denote the induced subgraph of $G$ on $V'$, and use $\partial_G(V')$ to denote the set of edges with one endpoint in $V'$ and another endpoint in $V\cut V'$. 

Let $\calP$ be a vertex partition of $V$ for graph $G$.
We call each set in $\calP$ a cluster. 
We say an edge of $G$ is an intercluster edge with respect to $\calP$ if the two endpoints of the edge belong to different clusters, otherwise, the edge is an intracluster edge. 
We use $G[\calP]$ to denote the union of the induced subgraphs on all the clusters in $\calP$ on $G$, i.e., $G[\calP] = (V, E')$ where $E' = \{(u, v, \alpha) \in E: \exists P \in \calP \text{ s.t. } u, v\in P\}$. 
We use $\partial_G(\calP)$ to denote the union of $\partial_G(P)$ for all the $P \in \calP$, i.e., the intercluster edges with respect to $\calP$.
A vertex is a boundary vertex with respect to $\calP$ if there exists an intercluster edge incident to the vertex. 

A \textit{cut} is a bipartition of the graph vertices. The \textit{cut-set} of a cut is the set of edges with two endpoints belonging to different sides of the cut. The \textit{size of a cut} is the sum of edge multiplicities for all the edges in the cut's cut-set. 
For a given positive integer $c$, we say a cut is a \textit{$c$-cut} if the size of the cut is at most $c$. 

\vspace{.15cm}\noindent \textbf{Expander Decomposition \ \ }

\def\truefactor{2^{\delta \log^{1/3} n \log^{2/3} \log n}}

\begin{Definition}[Expander and Expander Decomposition]
For a graph $G = (V, E)$ of $n$ vertices and $m$ edges,  the conductance of $G$ is 
$$\min_{\emptyset\subsetneq S\subsetneq V}\frac{\abs{\partial_G(S)}}{\min\set{\vol_G(S), \vol_G(V\cut S)}}$$
A graph $G$ is a $\phi$-expander if the conductance of $G$ is at least $\phi$.

A $(\phi, \epsilon)$-expander decomposition of $G$ is a vertex partition $\mathcal P$ of $V$ such that for each $P\in\mathcal P$, the induced subgraph $G[P]$ is a $\phi$-expander, and the number of intercluster edges is at most $\epsilon \cdot m$. 
For convenience, a $(\phi, \epsilon)$-expander decomposition is also called a $\phi$-expander decomposition. 
\end{Definition}

\section{Review: Multi-level Terminal Edge Connectivity Data Structure}\label{sec:js20_review}

For a set of terminal vertices $T\subset V$, a cut is called a \textit{terminal cut} if the cut partitions $T$ into two non-empty sets, otherwise, the cut is called a \textit{non-terminal cut}. 
Terminal cuts for terminal set $T$ that are also $c$-cuts are called \emph{$(T, c)$-cuts}. A $(T, c)$-cut that partitions $T$ into $T'$ and $T\cut T'$ is called a $(T', T\cut T', c)$-cut.

\begin{Definition}[cut containment set]\label{def:cut_containment_set}
Let $G = (V, E)$ be a graph, $T\subset V$ be a terminal set, and $c$ be a positive integer. 
A set of edges $CC$ is a $c$-cut containment set with respect to $T$ if $CC$ corresponds to intercluster edges of a vertex partition of $G$, and
for every bipartition $(T', T\cut T')$ of $T$ such that $G$ has a $(T', T\cut T', c)$-cut, there exists a minimum $(T', T\cut T', c)$-cut $C$ such that all the edges in the cut-set of $C$ are in $CC$.
\end{Definition}

Given a graph $G$, a vertex partition $\calP$ of $G$, positive integers $c, \gamma$ such that $\gamma > c$, a $c$-cut containment set $CC$ for $G$ and $\calP$,  and an unweighted spanning forest $F$ of $G\setminus CC$,
the terminal $c$-edge connectivity sparsifier of $G$ with respect to $\calP$, $CC$ and $F$ is constructed as follows: start from $G$, for each $P \in \calP$, replace $G[P]$ in $G$ by 
\[\sparsifier_{c, \gamma}(G[P], T_{G, \calP}\cap P, CC\cap E(G[P]), F[P]).\]
Recall here that $T_{G, \calP}=\endpoints(\partial_G(\calP))$.
We use $\sparsifier_{c, \gamma}(G, \calP, CC, F)$ to denote the resulting sparsifier.

A one-level terminal edge connectivity data structure contains an input graph $G$, a vertex partition $\calP$, a cut containment set $CC$, an unweighted spanning forest $F$ of $G\setminus CC$, the corresponding terminal edge connectivity sparsifier $\sparsifier_{c, \gamma}(G, \calP, CC, F)$ for some positive integers $c$ and $\gamma$, and other auxiliary data structure so that when updates of $G$ occur, $\calP$ and $CC$, $F$, and their corresponding terminal edge connectivity sparsifier can be updated efficiently.

We use $(G, \calP, CC, F)$ to denote the one-level terminal edge connectivity data structure with respect to given $G, \calP$, $CC$, and $F$, which consists of $\sparsifier_{c, \gamma}(G, \calP, CC, F)$.

The update sequence consists of the multigraph update operations defined in Section~\ref{sec:preliminary}. 
Let $\updateseq$ be an update sequence. We use $|\updateseq|$ to denote the length of the update sequence.

\subsection{Multi-Level Terminal Edge Connectivity Data Structure}\label{sec:multi-s-t-ds}

A multi-level terminal edge connectivity data structure with parameters $c, \phi$, and  $\gamma$
is a set of one-level data structures $\set{(G^{(i)}, \mathcal P^{(i)}, CC^{(i)}, F^{(i)})}_{i=0}^\ell$ satisfying the following conditions:
\begin{enumerate}
    \item[(c1)] $(G^{(i)}, \calP^{(i)}, CC^{(i)}, F^{(i)})$ is a one-level terminal edge connectivity data structure with parameters $c, \phi$  and $\gamma$.     \item[(c2)]  $G^{(0)}$ is the input graph, and $G^{(i)} = \sparsifier_{c, \gamma} (G^{(i-1)}, \mathcal P^{(i-1)}, CC^{(i-1)}, F^{(i)})$ for each $0 < i \leq \ell$.

    \item[(c3)] $\calP^{(\ell)}$ contains only one cluster.
    \end{enumerate}

\section{Minimum \texorpdfstring{$c$}{c}-Cut Data Structure}\label{sec:min-c-cut}

\subsection{Local Cut}

\begin{Definition}\label{def:local_cut}
Let $G = (V, E)$ be a graph with $T$ as terminals, and $\alpha, c$ be two positive integers. We say a cut $C = (U, V\cut U)$ is an $(\alpha, c)$-local cut in $G$ with respect to $T$ if all of the following conditions hold
\begin{itemize}
    \item The size of cut $C$ is at most $c$;
    \item Either $U$ or $V\cut U$ has volume at most $\alpha$ in $G$;
    \item $T\subset U$ or $T\subset V\cut U$.
\end{itemize}
A cut $C$ is a minimum $(\alpha, c)$-local cut in $G$ with respect to $T$ if $C$ is a $(\alpha, c)$-local cut in $G$ with respect to $T$ and there is no other $(\alpha, c)$-local cuts in $G$ with respect to $T$ with the size smaller than $C$.
\end{Definition}

