\subsection{The Global Min-Cut Sparsifier Data Structure}\label{sec:init_update}

\begin{Definition}\label{def:aux-graph}
 For a graph $G = (V, E)$ and a partition $\mathcal P$ of $V$,
 the auxiliary graph of $G$ with respect to $\mathcal P$, denoted as $G_*$,  is obtained from $G$ as follows: 
 For each $P\in\mathcal P$, add a special terminal vertex $t_P$ and connect $t_P$ to every terminal vertex in $P$. 

 The auxiliary partition $\calP_*$ is defined as  $\{P_* | P\in \mathcal P\}$, where $P_* = P\cup \set {t_P}$. 
The terminals of $G_*$ with respect to $\calP_*$ are the terminals of $G$ with respect to $\calP$ union all the special terminals.
 \end{Definition}

\begin{Definition}[One-level Sparsifier]\label{def:lambda}
 Given parameters $c, \phi$, $c'\geq c$, $\gamma\geq c'$,  and $\alpha\geq \ceil{c/\phi}$, a one-level global minimum cut data structure w.r.t. these parameters consists of two parts:
\begin{enumerate}
    \item[(1)] A one-level terminal edge connectivity data structure  $\sparsifier_{c', \gamma}(G, \calP, CC, F)$ (Section \ref{sec:js20_review}), which contains the input graph $G = (V, E)$, a vertex partition $\calP$ of $G$ given by a $\phi$-expander decomposition, and a $c'$-cut containment set $CC$ with respect to $G$ and $\calP$.

    \item[(2)] Assuming $G_*$ is the auxiliary graph of $G$ with respect to $\mathcal P$, a priority queue $\Lambda_{G_*}$ that contains all vertex sets $U$ such that
    \begin{itemize}
    \item There exists a $P\in\mathcal P$ such that $U\subset P_*$, where $P_*$ is the corresponding cluster of $P$ in $G_*$
    \item $U$ induces a connected subgraph in $G_*$
    \item  $(U, P_*\cut U)$ is a $(3\alpha, c)$-local cut in $G_*[P_*]$. The terminal set is $(\endpoints(\partial_G(\mathcal P))\cap P) \cup\set{t_P}$.
        \end{itemize}
The elements in $\Lambda_{G_*}$ are ordered by the size of each cut $(U, P_*\cut U)$.
\end{enumerate}
\end{Definition}

In summary, a one-level global minimum cut sparsifier data structure is a tuple $(G, \mathcal P, CC, F, \Lambda_{G_*})$, where $(G, \mathcal P, CC, F)$ is a one-level terminal edge connectivity sparsifier, and $\Lambda_{G_*}$ is a priority queue of vertex sets.

A multi-level global minimum cut data structure 
    $$\set{(G^{(j)}, \mathcal P^{(j)}, CC^{(j)}, F^{(j)},\Lambda_{G_*^{(j)}}) }_{j=1}^{\ell}$$
 contains a set of $\ell$ one-level  global minimum cut data structures such that conditions (c1), (c2) and (c3) in Section~\ref{sec:multi-s-t-ds} hold.

