\begin{lemma}\label{lem:one-up-new}
Given a one-level minimum cut data structure $(G, \calP, CC, F, \Lambda_{G_*})$ with parameters $c, \phi, c',  \gamma, \alpha$ satisfying the following inequalities 
\[c' = c^2 + 2c,\gamma > c',  \alpha \geq (c^2 + 2c)\cdot 2^{O(\log^{1/3}n\log\log n)} / \phi, \text{ and } \phi \leq \frac{1 }{2^{\log^{3/4} n}},\]
and an update sequence $\updateseq$ of $G$ which consists of vertex/edge insertions/deletions, 
there is an algorithm 
\Fdeltaupdate of running time $O(|\updateseq|)\cdot O(\alpha)^{O(c^2)}$ which updates the data structure to $(G', \calP', CC', F',\Lambda_{G'_*})$ with parameters $c, \phi/2^{O(\log^{1/3}n\log\log n)}$, $c$, $\gamma, \alpha$, and outputs an update sequence $\updateseq'$ satisfying the following properties:
\begin{enumerate}

    \item $G'$ is the resulted graph of applying $\updateseq$ to $G$.
    \item $\calP'$ is a $\phi/2^{O(\log^{1/3}n\log\log n)}$-expander decomposition of $G'$. Furthermore, each cluster $P'\in\mathcal P'$ either contains only a single vertex or is a subset of a cluster $P\in \mathcal P$ such that $G'[P'] = G[P']$.
    \item $CC'$ is a $c$-cut containment set for $G'$ and $\calP'$. 
    \item $F'$ is an unweighted spanning forest of $G'\setminus CC'$.     

    \item The sparsifier maintained in the data structure is $\sparsifier_{c, \gamma}(G', \calP', CC', F')$.
    \item $\updateseq'$ updates $\sparsifier_{c', \gamma}(G, \calP, CC, F)$ to $\sparsifier_{c, \gamma}(G', \calP', CC', F')$. The length of $\updateseq'$ is at most $\abs{\updateseq}(10c)^{O(c)}$
    \item $\Lambda_{G'_*}$ is a priority queue containing every vertex set $U'$ such that
    \begin{itemize}
 \item There exists a $P'\in\mathcal P'$ such that $U'\subset P'_*$, where $P'_*$ is the corresponding cluster of $P'$ in $G'_* = (V_*', E_*')$
    \item $U'$ induces a connected subgraph in $G'_*$
    \item  $(U', P'_*\cut U')$ is an $(3\alpha, c)$-local cut in $G'_*[P'_*]$  for some $\alpha\geq \ceil{c/\phi}$. The terminal set is $\endpoints(\partial_{G'}(\mathcal P'))\cap P' \cup\set{t_{P'}}$.
\end{itemize}
The priority of vertex subsets in $\Lambda_{G'_*}$ is given by the size of $(U', V'_*\cut U')$ in increasing order.

    \end{enumerate}
\end{lemma}

